import { appendFileSync } from "node:fs";
import { join } from "node:path";
import { DIRS, ensureDirs } from "./config.ts";

export type LogLevel = "debug" | "info" | "warn" | "error";

function logPath(): string {
  const day = new Date().toISOString().slice(0, 10);
  return join(DIRS.logs, `glint-${day}.log`);
}

export function log(level: LogLevel, event: string, data?: unknown): void {
  try {
    ensureDirs();
    const line =
      JSON.stringify({
        ts: new Date().toISOString(),
        level,
        event,
        ...(data !== undefined ? { data } : {}),
      }) + "\n";
    appendFileSync(logPath(), line, { mode: 0o600 });
  } catch {
    // Logging must never crash the app.
  }
}

export const logger = {
  debug: (event: string, data?: unknown) => log("debug", event, data),
  info: (event: string, data?: unknown) => log("info", event, data),
  warn: (event: string, data?: unknown) => log("warn", event, data),
  error: (event: string, data?: unknown) => log("error", event, data),
};
